sys_ux_client_script.required_translations:
[
    {
        "message": "Relevant details for this call"
    },
    {
        "message": "Generated by Now Assist. Check for accuracy."
    },
    {
        "message": "Context updated"
    },
    {
        "message": "Refresh"
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var headerLabel = helpers.translateSync('Relevant details for this call');
    return {
        'footerLabel': helpers.translateSync('Generated by Now Assist. Check for accuracy.'),
        'headerInitialLabel': headerLabel,
        'headerLoadingLabel': headerLabel,
        'headerLoadedLabel': headerLabel,
        'isRefreshDisabled': api.state.isRefreshDisabled,
        'manageRefresh': true,
        'refreshSummaryHelperText': helpers.translateSync('Context updated'),
        'refreshSummaryButtonText': helpers.translateSync('Refresh')
    };
}
